import { createCloudflareWorkflowProvider, type CloudflareWorkflowBinding } from '@cossackframework/framework/workflows/provider';
import { defineWorkflow, createWorkflowClient } from '@cossackframework/core/workflows';
const definition = defineWorkflow({name: 'receipt', version: 1,
  schema: {async parse(value: unknown) { if (typeof value !== 'string') throw Error('Invalid input'); return value; }}, events: {},
  async run(input, {step}) { return step.do('receipt', async () => ({received: input})); }});
// Like the native binding, get() rejects ids that were never created.
const created = new Set<string>();
const binding: CloudflareWorkflowBinding = {
  async create({id}) { created.add(id); },
  async get(id) { if (!created.has(id)) throw Error('Not found');
    return {async status() {return {status: 'errored', secret: 'PRIVATE'};},
      async sendEvent() {}, async pause() {}, async resume() {}, async terminate() {}}; }
};
const client = createWorkflowClient(definition, createCloudflareWorkflowProvider(binding), {namespace: 'demo',
  authorize(_operation, identity) { if (identity.scope.tenantId !== 'demo') throw Error('Denied'); }});
const identity = await client.invoke('receipt-id', {key: 'receipt-id', scope: {tenantId: 'demo'}});
const inspection = await client.inspect(identity);
if (inspection.status !== 'failed' || inspection.code !== 'WORKFLOW_FAILED' || JSON.stringify(inspection).includes('PRIVATE')) throw Error('Unsafe inspection');

import { createSessionMiddleware, session, type SessionStore } from '@cossackframework/framework/session';
export function sessionMiddleware(storeForRequest: () => Promise<SessionStore>) {
  return createSessionMiddleware({store: () => storeForRequest(), cookieName: 'app_sid', ttl: 60 * 60 * 1000});
}
export async function savePreference(theme: 'light' | 'dark') {
  const current = session();
  await current.set('theme', theme);
  return current.get<'light' | 'dark'>('theme');
}

import { filePathToRoutePath, resolveStaticRoutePath } from '@cossackframework/framework/route-ids';
import { createMarkdownProcessor } from '@cossackframework/framework/markdown-processor';
import { checkCapabilityRequirements } from '@cossackframework/framework/runtime-capabilities';
const route = filePathToRoutePath('/src/pages/[lang]/article.ts');
if (resolveStaticRoutePath(route, {lang: 'fr'}) !== '/fr/article') throw Error('Wrong route');
const processor = createMarkdownProcessor<{readingMinutes: number}>({extensions: {
  readingMinutes: (value): value is number => typeof value === 'number' && value >= 0,
}});
const article = await processor('---\ntitle: Guide\nlocale: fr\nreadingMinutes: 2\n---\n# Guide', 'src/pages/fr/article.md');
if (article.frontmatter.locale !== 'fr') throw Error('Missing locale');
const diagnostics = checkCapabilityRequirements('node', [{feature: 'durable-page', source: {file: 'src/pages/live.ts'}, requires: {durableState: true}}]);
if (!diagnostics.length) throw Error('Durable page requires Cloudflare');

import { Hono } from 'hono';
import { Cossack, input } from '@cossackframework/core';
import { defineApi } from '@cossackframework/framework/api';
import { createApiHandler } from '@cossackframework/framework/api-handler';
const query = input.object({name: input.string()});
const output = input.object({greeting: input.string()});
const app = new Hono();
app.get('/greeting', defineApi({input: {query}, output,
  authorize: ({c}) => c.req.header('Authorization') === 'Bearer fixture',
  handler: ({input}) => ({greeting: 'Hello ' + input.query.name})}));
class Health extends Cossack { async get() { return this.c.json({healthy: true}); } }
app.get('/health', createApiHandler(Health, 'get'));
const fetch = (request: Request) => app.fetch(request);
const denied = await fetch(new Request('https://app.example.test/greeting?name=Ada'));
if (denied.status !== 403) throw Error('Unauthorized API must reject');
const response = await fetch(new Request('https://app.example.test/greeting?name=Ada', {headers: {Authorization: 'Bearer fixture'}}));
if (!response.ok || (await response.json() as {greeting: string}).greeting !== 'Hello Ada') throw Error('Invalid API result');
if (!(await fetch(new Request('https://app.example.test/health'))).ok) throw Error('Class API failed');

import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Cossack, detectBrowserLocale } from '@cossackframework/core';
import { getSiteUrl } from '@cossackframework/framework/ssg-config';
import { generateSitemap } from '@cossackframework/framework/sitemap-generator';
class Article extends Cossack {}
const root = await mkdtemp(join(tmpdir(), 'cossack-site-guide-'));
try {
  await writeFile(join(root, '.env'), 'APP_URL=https://app.example.test\n');
  const baseUrl = getSiteUrl({projectRoot: root});
  const selected = detectBrowserLocale('fr-FR, en;q=0.8', ['en', 'fr'], 'en');
  if (selected !== 'fr') throw Error('Wrong language preference');
  const sitemap = generateSitemap(['en', 'fr'].map(locale => ({routePath: '/' + locale + '/article', filePath: '/src/pages/' + locale + '/article.ts', component: Article})), {baseUrl, lastmod: new Date('2026-01-01')});
  if (!sitemap.includes(baseUrl.replace(/\/$/, '') + '/en/article') || !sitemap.includes('/fr/article')) throw Error('Missing static URL');
} finally { await rm(root, {recursive: true, force: true}); }

import { mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { inspectConfigRequirements } from '@cossackframework/framework/config-inspection';
import { inspectConfigurationRequirements } from '@cossackframework/framework/config-preflight';
import { resolveLayoutPaths } from '@cossackframework/framework/route-ids';
const root = await mkdtemp(join(tmpdir(), 'cossack-inspection-guide-'));
try {
  await mkdir(join(root, 'src/config'), {recursive: true});
  await writeFile(join(root, 'src/config/app.ts'), "export const requirements = {variables: {API_TOKEN: {type: 'string', secret: true, required: true}}}; export default () => ({token: 'PRIVATE_SENTINEL'});");
  const requirements = await inspectConfigRequirements(root);
  const checked = await inspectConfigurationRequirements(root, {runtime: 'node'});
  const serialized = JSON.stringify({requirements, checked});
  if (!serialized.includes('API_TOKEN') || serialized.includes('PRIVATE_SENTINEL')) throw Error('Unsafe source inspection');
  const layouts = resolveLayoutPaths('/src/pages/account/settings.ts', ['/src/pages/layout.ts', '/src/pages/account/layout.ts']);
  if (layouts.length !== 2) throw Error('Missing nested ownership');
} finally { await rm(root, {recursive: true, force: true}); }
